const RETRY_STATUS = new Set([408, 425, 429, 500, 502, 503, 504]);

/** True for the failures a second attempt can plausibly fix (throttle/timeout). */
function isTransient(err) {
  if (err && err.transient) return true;
  if (err && (err.name === 'AbortError' || err.name === 'TimeoutError')) return true;
  return /fetch failed|ECONNRESET|ECONNREFUSED|ETIMEDOUT|EAI_AGAIN|socket hang up/i.test(String(err?.message || ''));
}

async function get(url, { as = 'text', timeout = 25000, attempts = 3 } = {}) {
  const file = cacheFile(url, as);
  if (OFFLINE) {
    const cached = await readFile(file, 'utf8');
    return as === 'json' ? JSON.parse(cached) : cached;
  }
  for (let attempt = 1; ; attempt += 1) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeout);
    try {
      const res = await fetch(url, {
        headers: { 'user-agent': UA, accept: as === 'json' ? 'application/json' : '*/*' },
        signal: ctrl.signal,
      });
      if (!res.ok) {
        const err = new Error(`${res.status} ${url}`);
        // Only a throttle or a server fault is worth a retry; a 404 stays an error.
        err.transient = RETRY_STATUS.has(res.status);
        throw err;
      }
      const body = as === 'json' ? await res.json() : await res.text();
      await mkdir(CACHE_DIR, { recursive: true });
      await writeFile(file, as === 'json' ? JSON.stringify(body) : body);
      return body;
    } catch (err) {
      if (!isTransient(err) || attempt >= attempts) throw err;
      // 400 ms, 800 ms … plus jitter: polite enough for a library's rate limiter.
      await sleep(400 * attempt + Math.floor(Math.random() * 250));
    } finally {
      clearTimeout(timer);
    }
  }
}

